sys_variable_value.value:
(function execute(inputs, outputs) {

    // ==========================================
    // 1. Get Reserved For User
    // ==========================================

    var userName = '';

    var userGR = new GlideRecord('sys_user');

    if (userGR.get(inputs.reserved_for)) {
        userName = userGR.getDisplayValue();
    } else {
        userName = inputs.reserved_for;
    }


    // ==========================================
    // 2. Get Workspace Name
    // ==========================================

    var workspaceName = '';

    var workspaceGR = new GlideRecord('x_1209398_wrm_workspace_options');

    if (workspaceGR.get(inputs.workspace_name)) {
        workspaceName = workspaceGR.getDisplayValue();
    } else {
        workspaceName = inputs.workspace_name;
    }


    // ==========================================
    // 3. Get Start Date/Time
    // ==========================================

    var startDateTime = inputs.start_date_time;


    // ==========================================
    // 4. Build Reservation Tracker URL
    // ==========================================

    var trackerURL = '';

    if (inputs.tracker_record) {

        trackerURL =
            gs.getProperty('glide.servlet.uri') +
            'x_1209398_wrm_reservation_tracker.do?sys_id=' +
            inputs.tracker_record.getUniqueValue();
    }


    // ==========================================
    // 5. Build Discord Message
    // ==========================================

    var message =
        '**New Workspace Approval Required**\n\n' +
        '**User:** ' + userName + '\n' +
        '**Workspace:** ' + workspaceName + '\n' +
        '**Start Date/Time:** ' + startDateTime + '\n\n' +
        '**Reservation Record:**\n' +
        trackerURL + '\n\n' +
        '📌 Please claim this reservation if you will be handling it.';


    // ==========================================
    // 6. Send Discord Notification
    // ==========================================

    var discord = new discordNotification();

    discord.sendMessage(message, '🚨');

})(inputs, outputs);

